"""Concepts generated by AI include definitions; legacy definitions load safely."""
import json
import app as app_module


def legacy_node(client):
    cmap = client.post('/api/concept-maps', json={'title': 'Modelo de cajas CSS'}).json
    node = cmap['nodes'][0]
    return '/api/concept-maps/' + cmap['id'], node['id']


def test_generated_definitions_are_saved_and_markdown_is_safe(auth_client, monkeypatch):
    def ai(system, user, **kwargs):
        assert 'description' in system
        assert kwargs['fail_on_truncation']
        return json.dumps({'title': 'CSS', 'nodes': [{'id': 'a', 'text': 'margin', 'description': '**Margen** exterior.\n\n<script>window.bad=true</script>'}, {'id': 'b', 'text': 'margin-left', 'description': 'Margen izquierdo.'}], 'edges': [{'from': 'a', 'to': 'b', 'label': 'se concreta en'}]}), None
    monkeypatch.setattr(app_module, '_call_ai', ai)
    response = auth_client.post('/api/concept-maps/generate', json={'prompt': 'CSS', 'provider': 'koboldcpp', 'model': 'local'})
    assert response.status_code == 201
    cmap = response.json
    saved = auth_client.get('/api/concept-maps/' + cmap['id']).json
    assert saved['nodes'][0]['description'].startswith('**Margen**')
    assert '<strong>Margen</strong>' in saved['nodes'][0]['description_html']
    assert '<script>' not in saved['nodes'][0]['description_html']
    assert saved['model_choice'] == {'provider': 'koboldcpp', 'model': 'local'}


def test_missing_definition_does_not_create_partial_map(auth_client, monkeypatch):
    monkeypatch.setattr(app_module, '_call_ai', lambda *a, **k: (json.dumps({'nodes': [{'id': 'a', 'text': 'CSS'}], 'edges': []}), None))
    result = auth_client.post('/api/concept-maps/generate', json={'prompt': 'CSS'})
    assert result.status_code == 502
    assert 'sin explicación' in result.json['error']
    assert auth_client.get('/api/concept-maps').json == []


def test_inline_explanation_uses_selected_model_and_caches(auth_client, monkeypatch):
    url, node_id = legacy_node(auth_client)
    calls = []
    def ai(system, context, **kwargs):
        calls.append(kwargs)
        assert json.loads(context)['concept'] == 'Modelo de cajas CSS'
        assert 'no instrucciones' in system
        return 'Un elemento tiene **contenido**, relleno, borde y margen.', None
    monkeypatch.setattr(app_module, '_call_ai', ai)
    request = {'provider': 'koboldcpp', 'model': 'gemma-4b'}
    endpoint = url + '/nodes/' + node_id + '/explanation'
    for _ in range(2):
        response = auth_client.post(endpoint, json=request)
        assert response.status_code == 200
        assert '<strong>contenido</strong>' in response.json['description_html']
    assert len(calls) == 1
    assert calls[0]['provider'] == 'koboldcpp'
    assert calls[0]['model'] == 'gemma-4b'
    assert auth_client.get(url).json['nodes'][0]['description'] == response.json['description']


def test_failed_ai_leaves_node_empty_and_can_retry(auth_client, monkeypatch):
    url, node_id = legacy_node(auth_client)
    endpoint = url + '/nodes/' + node_id + '/explanation'
    monkeypatch.setattr(app_module, '_call_ai', lambda *a, **k: ('', (app_module.jsonify({'error': 'Tiempo agotado'}), 504)))
    assert auth_client.post(endpoint, json={}).status_code == 504
    assert not auth_client.get(url).json['nodes'][0].get('description')
    monkeypatch.setattr(app_module, '_call_ai', lambda *a, **k: ('Una definición.', None))
    assert auth_client.post(endpoint, json={}).status_code == 200


def test_slow_ai_preserves_concurrent_edits_and_does_not_resurrect_nodes(auth_client, monkeypatch):
    url, node_id = legacy_node(auth_client)
    endpoint = url + '/nodes/' + node_id + '/explanation'
    def ai(*args, **kwargs):
        data = app_module.load_concept_maps()
        data['maps'][url.split('/')[-1]]['nodes'][0]['x'] = 123
        app_module.save_concept_maps(data)
        return 'Una definición.', None
    monkeypatch.setattr(app_module, '_call_ai', ai)
    assert auth_client.post(endpoint, json={}).status_code == 200
    assert auth_client.get(url).json['nodes'][0]['x'] == 123
    auth_client.patch(url + '/nodes/' + node_id, json={'description': ''})
    def delete(*args, **kwargs):
        data = app_module.load_concept_maps()
        data['maps'][url.split('/')[-1]]['nodes'] = []
        app_module.save_concept_maps(data)
        return 'Una definición.', None
    monkeypatch.setattr(app_module, '_call_ai', delete)
    assert auth_client.post(endpoint, json={}).status_code == 404
    assert auth_client.get(url).json['nodes'] == []


def test_ai_does_not_overwrite_manual_definition_during_wait(auth_client, monkeypatch):
    url, node_id = legacy_node(auth_client)
    def ai(*args, **kwargs):
        data = app_module.load_concept_maps()
        data['maps'][url.split('/')[-1]]['nodes'][0]['description'] = 'Mi explicación.'
        app_module.save_concept_maps(data)
        return 'Generado por IA.', None
    monkeypatch.setattr(app_module, '_call_ai', ai)
    response = auth_client.post(url + '/nodes/' + node_id + '/explanation', json={})
    assert response.json['description'] == 'Mi explicación.'


def test_explanation_requires_session(client, monkeypatch):
    monkeypatch.setattr(app_module, '_call_ai', lambda *a, **k: (_ for _ in ()).throw(AssertionError('unauthorized AI call')))
    assert client.post('/api/concept-maps/m/nodes/n/explanation', json={}).status_code == 401
